def reader(fname):
    with open(fname,'r') as f:
        return [x.rstrip('\n') for x in f]

# ------------------------------------------------------------------------
#                  Seek Points
# ------------------------------------------------------------------------

def seek_point(data,target):
    T,A   =  data.transpose()
    all_T =  np.array([T[i] for i in range(1,len(T)-1) if (((A[i-1]<A[i]) and (A[i+1]<A[i])) or
                                                           ((A[i-1]>A[i]) and (A[i+1]>A[i])))])
    return all_T[np.argmin(np.fabs(all_T - target))]

# ------------------------------------------------------------------------
#                  Split Fit
# ------------------------------------------------------------------------

def split_fit(x, y, x_knots):
    y_knots  =  interp1d(x,y,kind='cubic',fill_value="extrapolate")(x_knots)
    return CubicSpline(x_knots, y_knots), x_knots

# ------------------------------------------------------------------------
#                  Get Transformation
# ------------------------------------------------------------------------

def apply_transform(path, transform):
    a,b,c,d,e,f  =  lmap(float, transform.split('(')[1].split(')')[0].split(','))
    fx           =  lambda x,y: a*x + c*y + e
    fy           =  lambda x,y: b*x + d*y + f
    return np.array([f(*path.transpose()) for f in [fx,fy]]).transpose()

# ------------------------------------------------------------------------
#                  Get Curve
# ------------------------------------------------------------------------

def get_curve(D,n=100,is_markers=False):
    p = D['d']
    if type(p) == str: p = svpt.parse_path(p)
    if is_markers:
        all_p  =  p.continuous_subpaths()
        xy     =  np.array([np.average(get_curve(dict(d=p),n=n),axis=0) for p in all_p])
    else:
        all_c =  np.linspace(0,1,n) if n>1 else [0.5]
        xy    =  np.array(lmap(p.point,all_c))
        xy    =  np.array([xy.real, xy.imag]).transpose()
        if (n>1) and (np.fabs(xy[0,:] - xy[-1,:]).max() < 1e-10):
            xy = xy[:-1,:]
    result = np.array(sorted(xy.tolist()))
    if 'transform' in D:
        result = apply_transform(result,D['transform'])
    return result 

def f_merge(all_A, tol=1e-10):
    assert all((A.shape[1]==2) for A in all_A)
    x,y     =  [np.array([val for A in all_A for val in A[:,j]]) for j in range(2)]
    m       =  np.argsort(x)
    x,y     =  x[m], y[m]
    result  =  []
    prev    =  float('-inf')
    for i in range(len(x)):
        if abs(x[i]-prev) < tol: continue
        result.append([x[i],y[i]])
        prev = x[i]
    return np.array(result)

