    # ------- BEGIN: MANUAL DATA -------
    delta    = 0.5e-3
    ref_data = dict(P_dns   = 8e6                  , # pr = 1.14
                    T_pb    = 307.8                ,
                    rho_pb  = 462.727153614        ,
                    mu_pb   = 0.0000321780494071,
                    T0      = 297.8             , # Tr = 0.79
                    T1      = 317.8             , # Tr = 1.51
                    Ly      = 2*delta           ,
                    Lx      = 8*delta           ,
                    Lz      = 4*delta           ,
                    Nx      = 576               ,
                    Nz      = 576               ,
                    Ny      = 576               ,
                    Re_bulk = 5705              )
    # ------- END: MANUAL DATA -------    

    ref_data['U_bulk'] = ref_data['Re_bulk']/(ref_data['Ly']*ref_data['rho_pb']/ref_data['mu_pb'])
    T1_fit = ref_data['T1']
    curves_nist, curves_svg =  scanned_data_wan(data_refprop_CO2, ref_data, n0 = 10_000, do_plot = True)
    curves_svg = {key: (A if ('profile_y' in key) else A[(ref_data['T0']<=A[:,0])*(A[:,0]<=ref_data['T1'])])  for  key,A  in  curves_svg.items()}
    mk_drho_dt(curves_nist)

    rho_midpoint =  get_avg_zero_point(*curves_svg['rho_profile_y'].transpose().tolist())
    print(f"{rho_midpoint = }")

    def get_cen_fit(curves_nist, curves_svg, key, T0_dns, T1_dns, T1_lim, do_plot = True, plot_T_points = True, params = None):
        LL        =  1
        x,y       =  curves_nist[key].transpose().copy()
        i0        =  max(0     , len(x[x < T0_dns])-1)
        i1        =  min(len(x), len(x) - len(x[x > T1_dns]) + 1)
        x         =  x[i0:i1]
        y         =  y[i0:i1]
        del i0,i1
        assert (x.min() <= T0_dns) and (T1_dns <= x.max())
        x_knots      =  []
        T_break, T_break_pre, T_break_post  = T_seps =  params[0]
        params                                       =  params[1:]
        T_seps = [T0_dns, *list(T_seps), T1_lim]
        def conv(val):
            if val == 'min'  : return x.min()
            if val == 'max'  : return x.max()
            if val == 'pre'  : return T_break_pre
            if val == 'post' : return T_break_post
            if val == 'break': return T_break
            else             : 1/0
        if (not (T_break is None)):
            for mode_fit in range(len(params)):
                if     mode_fit == 0:  x0, x1, nk, KK  =  params[mode_fit]
                elif   mode_fit == 1:  x0, x1, nk, KK  =  params[mode_fit]
                elif   mode_fit == 2:  x0, x1, nk, KK  =  params[mode_fit]
                elif   mode_fit == 3:  x0, x1, nk, KK  =  params[mode_fit]
                else                :  1/0
                x0 = conv(x0)
                x1 = conv(x1)
                loc_x_knots  =  np.linspace(0,1,int(np.ceil((x1-x0)/nk+1)))
                loc_x_knots  =  loc_x_knots**(KK if KK<1 else (1/KK))
                if KK>1: loc_x_knots = (1-loc_x_knots)[::-1]
                loc_x_knots = loc_x_knots*(x1-x0) + x0
                if mode_fit<(len(params)-1): loc_x_knots = loc_x_knots[:-1]
                x_knots.extend(loc_x_knots.tolist())
        x_knots   =  np.array(x_knots)
        f, knots  =  split_fit(np.array(x), np.array(y), np.array(x_knots))
        if do_plot:
            fig           =  plt.figure()
            if key in curves_svg:
                x_svg, y_svg  =  curves_svg[key].transpose().copy()
                plt.plot(x_svg, LL*y_svg, 'g:',ms=1,label='svg_data')
            plt.plot(x    , LL*y    , 'b*',ms=1,label='base_data')
            plt.plot(x    , LL*f(x) , 'r',alpha=0.5,label='spline')
            plt.plot(knots, LL*f(knots),'go',alpha=0.5,label='spline_knots')
            if plot_T_points:
                [plt.plot([x,x], [LL*y.min(), LL*y.max()],'k:',label=('T_sep' if i_x==0 else None)) for i_x,x in enumerate(T_seps) if not (x is None)]
                if not LL:
                    [plt.plot([x,x], [-0.1, 0.1],'k:',label='T_sep') for x in T_seps if not (x is None)]
            title = f'spline_{key}_arr'
            plt.legend()
            plt.title(title + f'_(n_{len(x_knots)})')
            plt.savefig(pjoin(_folder_,'output',f'{title}.png'))
            plt.close(fig)
        return f
    
    # ------- BEGIN: MANUAL DATA -------
    inflection_T_cond = 307.8
    inflection_T_cp   = 307.8
    params_mu    = [[inflection_T_cond, inflection_T_cond-1, inflection_T_cond+1],
                    ['min'  , 'pre'  , 1.1   ,   0.6],
                    ['pre'  , 'break', 1.0/3 ,   0.6],
                    ['break', 'post' , 1.0/3 , 1/0.6],
                    ['post' , 'max'  , 1.1   , 1/0.6]]
    params_cond  = [[inflection_T_cond, inflection_T_cond-1, inflection_T_cond+1],
                    ['min'  , 'pre'  , 0.9   ,   0.6],
                    ['pre'  , 'break', 1.0/7 ,   0.6],
                    ['break', 'post' , 1.0/7 , 1/0.6],
                    ['post' , 'max'  , 0.9   , 1/0.6]]
    params_rho   = [[inflection_T_cond, inflection_T_cond-2, inflection_T_cond+2],
                    ['min'  , 'pre'  , 1.3   ,   0.6],
                    ['pre'  , 'break', 0.35  ,   0.6],
                    ['break', 'post' , 0.35  , 1/0.6],
                    ['post' , 'max'  , 1.3   , 1/0.6]]
    params_drho_dT = [[inflection_T_cond, inflection_T_cond-2, inflection_T_cond+2],
                    ['min'  , 'pre'  , 2.1    /2,   0.6],
                    ['pre'  , 'break', 0.35   /2,   0.6],
                    ['break', 'post' , 0.35   /2, 1/0.6],
                    ['post' , 'max'  , 2.1    /2, 1/0.6]]
    params_cp    = [[inflection_T_cp, inflection_T_cp-1, inflection_T_cp+1],
                    ['min'  , 'pre'  , 0.9   ,   0.6],
                    ['pre'  , 'break', 1.0/7 ,   0.6],
                    ['break', 'post' , 1.0/7 , 1/0.6],
                    ['post' , 'max'  , 0.9   , 1/0.5]]
    params_enth  = [[inflection_T_cond, inflection_T_cond-2, inflection_T_cond+2],
                    ['min'  , 'pre'  , 1.3   ,   0.6],
                    ['pre'  , 'break', 0.35  ,   0.6],
                    ['break', 'post' , 0.35  , 1/0.6],
                    ['post' , 'max'  , 1.3   , 1/0.6]]
    # ------- END: MANUAL DATA -------

    return  dict(mu           =  get_cen_fit(curves_nist, curves_svg, 'mu'      , ref_data['T0'], T1_fit, ref_data['T1'], plot_T_points = True,params=params_mu      ),
                 cond         =  get_cen_fit(curves_nist, curves_svg, 'cond'    , ref_data['T0'], T1_fit, ref_data['T1'], plot_T_points = True,params=params_cond    ),
                 rho          =  get_cen_fit(curves_nist, curves_svg, 'density' , ref_data['T0'], T1_fit, ref_data['T1'], plot_T_points = True,params=params_rho     ),
                 cp           =  get_cen_fit(curves_nist, curves_svg, 'cp'      , ref_data['T0'], T1_fit, ref_data['T1'], plot_T_points = True,params=params_cp      ),
                 drho_dT      =  get_cen_fit(curves_nist, curves_svg, 'drho_dT' , ref_data['T0'], T1_fit, ref_data['T1'], plot_T_points = True,params=params_drho_dT ),
                 enth         =  get_cen_fit(curves_nist, curves_svg, 'enth'    , ref_data['T0'], T1_fit, ref_data['T1'], plot_T_points = True,params=params_enth    ),
                 T0_dns       =  ref_data['T0'] ,
                 T1_dns       =  ref_data['T1'] ,
                 curves_nist  =  curves_nist    , 
                 curves_svg   =  curves_svg     ,
                 ref_data     =  ref_data       )

